<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store, no-cache, must-revalidate');
$dir=dirname(__DIR__,2).'/.restaurantes-data';
if(!is_dir($dir)&&!mkdir($dir,0750,true)&&!is_dir($dir)){http_response_code(500);echo json_encode(['error'=>'No se pudo crear almacenamiento']);exit;}
function readData($file){$v=file_exists($file)?json_decode((string)file_get_contents($file),true):[];return is_array($v)?$v:[];}
function writeData($file,$v){$tmp=$file.'.tmp';return file_put_contents($tmp,json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX)!==false&&rename($tmp,$file);}
function safeRest($r){if(isset($r['mercadoPagoConfig']))$r['mercadoPagoConfig']['accessToken']='';return $r;}
function reply($v,$code=200){http_response_code($code);echo json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
$rf=$dir.'/restaurants.json';$of=$dir.'/orders.json';$restaurants=readData($rf);$orders=readData($of);
$method=$_SERVER['REQUEST_METHOD']??'GET';$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$path=preg_replace('#^/Restaurantes#i','',$path);$path=rtrim($path,'/')?:'/';$body=json_decode((string)file_get_contents('php://input'),true)?:[];
if($path==='/api/restaurants'&&$method==='GET')reply(array_map('safeRest',$restaurants));
if($path==='/api/restaurants'&&$method==='PUT'){if(!is_array($body)||!array_is_list($body))reply(['error'=>'Formato de tarjetas inválido'],400);$old=$restaurants;foreach($body as &$r){foreach($old as $o)if(($o['slug']??'')===($r['slug']??'')){if(empty($r['mercadoPagoConfig']['accessToken']))$r['mercadoPagoConfig']['accessToken']=$o['mercadoPagoConfig']['accessToken']??'';break;}}unset($r);if(!writeData($rf,$body))reply(['error'=>'No se pudo guardar en almacenamiento del servidor'],500);reply(array_map('safeRest',$body));}
if($path==='/api/orders'&&$method==='GET'){$slug=$_GET['slug']??'';reply($slug?array_values(array_filter($orders,fn($o)=>($o['restaurantSlug']??'')===$slug)):$orders);}
if($path==='/api/orders'&&$method==='POST'){array_unshift($orders,$body);if(!writeData($of,$orders))reply(['error'=>'No se pudo registrar pedido'],500);reply($body,201);}
if(preg_match('#^/api/orders/([^/]+)$#',$path,$m)&&$method==='PATCH'){$id=rawurldecode($m[1]);$ok=false;foreach($orders as &$o)if(($o['id']??'')===$id){$o['orderStatus']=$body['orderStatus']??$o['orderStatus'];$o['updatedAt']=gmdate('c');$ok=true;break;}unset($o);if(!$ok)reply(['error'=>'Pedido no encontrado'],404);if(!writeData($of,$orders))reply(['error'=>'No se pudo actualizar pedido'],500);reply(['success'=>true]);}
if(preg_match('#^/api/analytics/([^/]+)/event$#',$path,$m)&&$method==='POST'){$slug=rawurldecode($m[1]);$ev=$body['event']??'';foreach($restaurants as &$r)if(($r['slug']??'')===$slug&&in_array($ev,['views','whatsappClicks','menuViews','qrScans'],true)){$r['analytics'][$ev]=(int)($r['analytics'][$ev]??0)+1;break;}unset($r);writeData($rf,$restaurants);reply(['success'=>true]);}
if($path==='/api/mercadopago/create-preference'&&$method==='POST'){$slug=(string)($body['restaurant_slug']??'');$token='';foreach($restaurants as $r)if(($r['slug']??'')===$slug){$token=$r['mercadoPagoConfig']['accessToken']??'';break;}if(!$token)reply(['error'=>'Falta configurar Access Token del restaurante'],422);$price=(float)($body['price']??0);if($price<=0)reply(['error'=>'Importe inválido'],400);$host=$_SERVER['HTTP_HOST']??'';$payload=['items'=>[['title'=>(string)($body['title']??'Pedido'),'quantity'=>max(1,(int)($body['quantity']??1)),'unit_price'=>$price,'currency_id'=>(string)($body['currency_id']??'MXN')]],'external_reference'=>(string)($body['external_reference']??uniqid('order-')),'back_urls'=>['success'=>'https://'.$host.'/Restaurantes/'.$slug.'/?payment=success','failure'=>'https://'.$host.'/Restaurantes/'.$slug.'/?payment=failure','pending'=>'https://'.$host.'/Restaurantes/'.$slug.'/?payment=pending'],'auto_return'=>'approved'];$ch=curl_init('https://api.mercadopago.com/checkout/preferences');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>25]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);if($raw===false||$status<200||$status>=300)reply(['error'=>'Mercado Pago rechazó la solicitud','detail'=>$err?:('HTTP '.$status)],502);$pref=json_decode((string)$raw,true);if(empty($pref['init_point']))reply(['error'=>'Mercado Pago no devolvió enlace'],502);reply(['id'=>$pref['id']??null,'init_point'=>$pref['init_point'],'sandbox_init_point'=>$pref['sandbox_init_point']??null]);}
reply(['error'=>'Ruta API no encontrada'],404);
